  "Ninguna señal coincide. Prueba otra palabra o agrega un detector propio describiéndolo abajo.": "Nenhum sinal corresponde. Tente outra palavra ou adicione um detector próprio descrevendo-o abaixo.",
  "Diseña tu plan de señales": "Monte seu plano de sinais",
  "La IA lee el contexto de tu empresa (qué vendes, a quién, en qué países) y lo que tu Intelligence Hub dice del mercado, y propone entre 5 y 10 detectores: cada uno una forma distinta de encontrar empresas que te necesitan ahora. Después los ajustas, los activas y corren solos.": "A IA lê o contexto da sua empresa (o que você vende, para quem, em quais países) e o que o seu Intelligence Hub diz sobre o mercado, e propõe de 5 a 10 detectores: cada um é uma forma diferente de encontrar empresas que precisam de você agora. Depois você ajusta, ativa e eles rodam sozinhos.",
