  "Avisos en el teléfono": "Alertas no celular",
  "Este dispositivo recibe una notificación cada vez que un lead te escribe por WhatsApp, email o LinkedIn, aunque Predictable esté cerrado. Al tocarla se abre la conversación.": "Este dispositivo recebe uma notificação sempre que um lead escreve para você por WhatsApp, e-mail ou LinkedIn, mesmo com o Predictable fechado. Ao tocar nela, a conversa é aberta.",
  "Recibe una notificación cuando un lead te escribe por WhatsApp, email o LinkedIn, aunque Predictable esté cerrado. Se activa por dispositivo: hazlo en cada teléfono o computadora donde quieras recibirlas.": "Receba uma notificação quando um lead escrever para você por WhatsApp, e-mail ou LinkedIn, mesmo com o Predictable fechado. A ativação é por dispositivo: faça isso em cada celular ou computador onde quiser recebê-las.",
  "En iPhone, Apple solo permite notificaciones a las apps de la pantalla de inicio (iOS 16.4 o más reciente). Son tres pasos:": "No iPhone, a Apple só permite notificações de apps adicionados à tela de início (iOS 16.4 ou mais recente). São três passos:",
  "Las notificaciones de Predictable están bloqueadas en este dispositivo. Para activarlas:": "As notificações do Predictable estão bloqueadas neste dispositivo. Para ativá-las:",
  "Solo avisa de mensajes recibidos, nunca de los que envías tú o tus campañas.": "Só avisa sobre mensagens recebidas, nunca sobre as que você ou suas campanhas enviam.",
