  "⚠ Tu cuenta no devolvió campañas. Crea en tu cuenta de automatización una campaña que SOLO mande la solicitud de conexión y pulsa \"Releer\".": "⚠ Sua conta não retornou campanhas. Crie na sua conta de automação uma campanha que envie SOMENTE a solicitação de conexão e clique em \"Ler novamente\".",
  "Campañas de LinkedIn creadas en Predictable": "Campanhas do LinkedIn criadas no Predictable",
  "Cada campaña manda UNA sola cosa: la solicitud de conexión, o un mensaje. Así la cadencia (a quién, cuándo y si todavía toca) la decide Predictable y se detiene en cuanto el lead responde por cualquier canal — una campaña con su propia secuencia seguiría escribiendo sola.": "Cada campanha envia UMA única coisa: a solicitação de conexão ou uma mensagem. Assim, a cadência (para quem, quando e se ainda é a vez) é decidida pelo Predictable e para assim que o lead responde por qualquer canal — uma campanha com sequência própria continuaria escrevendo sozinha.",
  "Ninguna todavía. Diseña el texto aquí, créala en tu cuenta con el mismo nombre y queda vinculada: los leads de tus cadencias se enrolan solos.": "Nenhuma ainda. Crie o texto aqui, crie a campanha na sua conta com o mesmo nome e ela fica vinculada: os leads das suas cadências são inscritos automaticamente.",
  "solo mensaje": "só mensagem",
  "solo conexión": "só conexão",
  "Ver pasos / vincular": "Ver etapas / vincular",
  "+ Campaña de conexión": "+ Campanha de conexão",
  "+ Campaña de mensaje": "+ Campanha de mensagem",
  "Paso 1: API key conectada.": "Passo 1: API key conectada.",
  "Paso 2: pega esta URL en cada campaña de LinkedIn → Settings → Webhooks, condición \"After LinkedIn reply is received\" (y otra con \"After message sent\" para ver en la bandeja lo que sale de tu cuenta). Así una respuesta por LinkedIn detiene la cadencia y llega a la bandeja, aunque el lead no esté en tus listas.": "Passo 2: cole esta URL em cada campanha do LinkedIn → Settings → Webhooks, com a condição \"After LinkedIn reply is received\" (e outra com \"After message sent\" para ver na Caixa de entrada o que sai da sua conta). Assim, uma resposta pelo LinkedIn interrompe a cadência e chega à Caixa de entrada, mesmo que o lead não esteja nas suas listas.",
  "URL no disponible: reconecta el canal.": "URL indisponível: reconecte o canal.",
  "Este paso no se puede automatizar: tu cuenta de automatización de LinkedIn no permite crear webhooks por API.": "Este passo não pode ser automatizado: sua conta de automação do LinkedIn não permite criar webhooks por API.",
  "Releer": "Ler novamente",
  "1 campaña de LinkedIn quedó vinculada a Dripify.": "1 campanha do LinkedIn foi vinculada ao Dripify.",
  "Cambiar API key": "Alterar API key",
  "Los emails de campaña salen como mensajes individuales desde tu cuenta; los datos revelados se cobran a los créditos de tu propia cuenta, no a los de la plataforma.": "Os e-mails das campanhas saem como mensagens individuais da sua conta; os dados revelados são cobrados dos créditos da sua própria conta, não dos da plataforma.",
  "Sin conectar.": "Não conectado.",
  "Conecta tu cuenta de Apollo para que las campañas envíen email desde tu buzón, con tus listas, tus contactos y tus créditos de Apollo.": "Conecte sua conta do Apollo para que as campanhas enviem e-mails da sua caixa de e-mail, com suas listas, seus contatos e seus créditos do Apollo.",
