  "Esta campaña tiene leads en curso. Si reemplazas la cadencia, el motor los sigue por el orden de los pasos nuevos; los pasos ya enviados no se repiten.": "Esta campanha tem leads em andamento. Se você substituir a cadência, o motor os conduz pela ordem das novas etapas; as etapas já enviadas não se repetem.",
  "Se descartan los pasos que tienes en la línea de tiempo.": "As etapas que você tem na linha do tempo serão descartadas.",
  "No hay conexión con el servidor.": "Sem conexão com o servidor.",
  "Cadencia recomendada lista. Revísala paso a paso.": "Cadência recomendada pronta. Revise etapa por etapa.",
  "No tienes créditos suficientes para la cadencia recomendada (6 créditos).": "Você não tem créditos suficientes para a cadência recomendada (6 créditos).",
  "Cada tarjeta es un envío. La espera cuenta desde el paso anterior; \"junto con el anterior\" sale a la misma hora. El \"+\" agrega WhatsApp, email, LinkedIn o una condición con ramas Sí / No que se vuelven a unir al final.": "Cada cartão é um envio. A espera conta a partir da etapa anterior; \"junto com a anterior\" sai no mesmo horário. O \"+\" adiciona WhatsApp, e-mail, LinkedIn ou uma condição com ramos Sim / Não que voltam a se juntar no final.",
  "Selecciona un paso": "Selecione uma etapa",
  "Toca una tarjeta para cambiar su canal, su espera y su contenido, o el \"+\" para agregar un paso.": "Toque em um cartão para mudar o canal, a espera e o conteúdo, ou no \"+\" para adicionar uma etapa.",
