  "Leads en campaña": "Leads na campanha",
  "Es el tope si todos los leads recorren toda la cadencia; se cobra paso a paso y se detiene con la primera respuesta.": "É o teto se todos os leads percorrerem a cadência inteira; a cobrança é feita etapa por etapa e para na primeira resposta.",
  "Se calcula con los leads de la lista: sin lista, el costo depende de cuántos enroles.": "É calculado com os leads da lista: sem lista, o custo depende de quantos você inscrever.",
  "Enviar emails desde": "Enviar e-mails de",
  "Elige el buzón de Apollo que firma los emails de esta campaña. El predeterminado se cambia en Campañas → Email.": "Escolha a caixa de e-mail do Apollo que assina os e-mails desta campanha. A padrão é alterada em Campanhas → E-mail.",
