  "Máx. emails / día": "Máx. e-mails / dia",
  "Los WhatsApp salen del número conectado; los emails, de la cuenta elegida. LinkedIn no lleva tope: el ritmo lo decide tu cuenta de LinkedIn. La ventana horaria y los días se aplican en la zona horaria indicada.": "Os WhatsApp saem do número conectado; os e-mails, da conta escolhida. O LinkedIn não tem limite: o ritmo é definido pela sua conta do LinkedIn. A janela de horário e os dias seguem o fuso horário indicado.",
  "Eliminar la condición": "Excluir a condição",
  "Eliminar el paso": "Excluir a etapa",
  "Los leads que estaban por recibir este paso pasan al siguiente.": "Os leads que iam receber esta etapa passam para a seguinte.",
  "Se pierde el texto que escribiste en este paso.": "O texto que você escreveu nesta etapa será perdido.",
  "La lista no tiene leads: no hay a quién enrolar.": "A lista não tem leads: não há ninguém para inscrever.",
  "Lanzar": "Lançar",
