  "Libre (según tus instrucciones)": "Livre (conforme suas instruções)",
  "LinkedIn ya envió la solicitud": "O LinkedIn já enviou a solicitação",
  "Dripify confirmó que la invitación salió de tu cuenta. Útil para esperar a que salga antes de contar los días.": "O Dripify confirmou que o convite saiu da sua conta. Útil para esperar o envio antes de contar os dias.",
  "Aceptó la conexión de LinkedIn": "Aceitou a conexão do LinkedIn",
  "Lo reporta tu cuenta de LinkedIn vía Dripify. Necesita un paso de conexión antes.": "Informado pela sua conta do LinkedIn via Dripify. Precisa de uma etapa de conexão antes.",
  "Le llegó el WhatsApp": "Recebeu o WhatsApp",
  "Doble check gris: WhatsApp entregó el mensaje. Si no llegó, ese número no tiene WhatsApp.": "Dois tiques cinza: o WhatsApp entregou a mensagem. Se não chegou, esse número não tem WhatsApp.",
  "Leyó el WhatsApp": "Leu o WhatsApp",
  "Doble check azul del WhatsApp.": "Dois tiques azuis do WhatsApp.",
  "El email salió y no rebotó": "O e-mail saiu e não voltou",
  "Se envió y el proveedor no reportó rebote ni bloqueo. (Nadie confirma la entrega real de un correo: solo el rebote.)": "Foi enviado e o provedor não informou devolução nem bloqueio. (Ninguém confirma a entrega real de um e-mail: só a devolução.)",
  "Abrió el email": "Abriu o e-mail",
  "Apertura registrada por el proveedor de email. Ojo: los filtros corporativos pueden abrirlo solos o bloquear el píxel.": "Abertura registrada pelo provedor de e-mail. Atenção: filtros corporativos podem abri-lo sozinhos ou bloquear o pixel.",
  "El email rebotó": "O e-mail voltou",
  "Rebote duro, rebote o bloqueo por spam. Sirve para saltar al teléfono en cuanto el correo muere.": "Devolução permanente, devolução ou bloqueio por spam. Serve para pular para o telefone assim que o e-mail morre.",
  "Dio alguna señal (abrió, leyó o aceptó)": "Deu algum sinal (abriu, leu ou aceitou)",
  "Cualquier señal de interés en cualquier canal: abrió un email, leyó un WhatsApp o aceptó la conexión.": "Qualquer sinal de interesse em qualquer canal: abriu um e-mail, leu um WhatsApp ou aceitou a conexão.",
  "Tiene teléfono": "Tem telefone",
  "El lead tiene un número revelado.": "O lead tem um número revelado.",
  "Tiene email": "Tem e-mail",
  "El lead tiene un email revelado.": "O lead tem um e-mail revelado.",
  "Tiene LinkedIn": "Tem LinkedIn",
  "El lead tiene URL de perfil.": "O lead tem URL de perfil.",
  "Hay dos pasos con el mismo id.": "Há duas etapas com o mesmo id.",
  "de solo conexión": "só de conexão",
  "de solo mensaje": "só de mensagem",
  "La condición no tiene pasos en ninguna rama.": "A condição não tem etapas em nenhum ramo.",
  "Agrega al menos un paso a la cadencia.": "Adicione pelo menos uma etapa à cadência.",
  "Omnicanal completo": "Omnichannel completo",
  "Conexión por LinkedIn; si la acepta, mensaje por LinkedIn; si no, WhatsApp. Según lea o no el WhatsApp, recordatorio o email de apertura; después valor, y según abra o no, prueba social o último WhatsApp. Cierra con la última carta. En cuanto responda por cualquier canal, la cadencia se detiene y la conversación pasa a tu Bandeja.": "Conexão pelo LinkedIn; se aceitar, mensagem pelo LinkedIn; se não, WhatsApp. Conforme ler ou não o WhatsApp, lembrete ou e-mail de abertura; depois valor e, conforme abrir ou não, prova social ou último WhatsApp. Fecha com a última cartada. Assim que responder por qualquer canal, a cadência para e a conversa vai para a sua Caixa de entrada.",
  "WhatsApp primero": "WhatsApp primeiro",
  "WhatsApp con el email de refuerzo el mismo día; si lo leyó, otro WhatsApp; si no, un email de valor. Cierra con un último WhatsApp y la última carta. Tú eliges la plantilla de cada WhatsApp.": "WhatsApp com o e-mail de reforço no mesmo dia; se leu, outro WhatsApp; se não, um e-mail de valor. Fecha com um último WhatsApp e a última cartada. Você escolhe o modelo de cada WhatsApp.",
  "Email primero": "E-mail primeiro",
  "Apertura por email; si lo abrió, seguimiento de valor; si no, WhatsApp. Luego prueba social, objeción preventiva y última carta.": "Abertura por e-mail; se abriu, acompanhamento de valor; se não, WhatsApp. Depois prova social, objeção preventiva e última cartada.",
  "LinkedIn primero": "LinkedIn primeiro",
  "Conexión por LinkedIn; a los 3 días, si aceptó, email de apertura; si no, WhatsApp y email en paralelo. Luego valor, recordatorio y última carta.": "Conexão pelo LinkedIn; após 3 dias, se aceitou, e-mail de abertura; se não, WhatsApp e e-mail em paralelo. Depois valor, lembrete e última cartada.",
  "junto con el anterior": "junto com a anterior",
  "día": "dia",
  "días": "dias",
  "Al enrolar": "Ao inscrever",
  "Enseguida": "Imediatamente",
