  "Una clave identifica a un sistema que se conecta a tu cuenta. Crea una por sistema y dale el menor permiso que necesite.": "Uma chave identifica um sistema que se conecta à sua conta. Crie uma por sistema e dê a ela a menor permissão necessária.",
