  "Conecta un agente de IA": "Conecte um agente de IA",
  "MCP (Model Context Protocol) es el estándar con el que los asistentes de IA usan herramientas externas. Conecta Predictable a Claude, ChatGPT, Cursor o tu propio agente y podrás pedirle cosas como «busca los leads que respondieron esta semana por WhatsApp» o «carga estos 40 contactos y ponlos en la campaña de octubre». Usa las mismas claves y permisos que la API: una clave de solo lectura solo deja consultar.": "MCP (Model Context Protocol) é o padrão com que os assistentes de IA usam ferramentas externas. Conecte o Predictable ao Claude, ChatGPT, Cursor ou ao seu próprio agente e você poderá pedir coisas como «encontre os leads que responderam esta semana pelo WhatsApp» ou «carregue estes 40 contatos e coloque-os na campanha de outubro». Usa as mesmas chaves e permissões da API: uma chave somente leitura só permite consultar.",
