  "Cada respuesta de un lead, cambio de estado, señal del Radar o reunión analizada llega a tu URL en segundos, firmada para que sepas que es nuestra.": "Cada resposta de um lead, mudança de status, sinal do Radar ou reunião analisada chega à sua URL em segundos, assinada para você saber que é nossa.",
  "Tu agente de IA opera Predictable": "Seu agente de IA opera o Predictable",
  "Conecta Claude, ChatGPT, Cursor o tu propio agente y pídele en lenguaje natural «carga estos leads y ponlos en la campaña de octubre».": "Conecte Claude, ChatGPT, Cursor ou seu próprio agente e peça em linguagem natural «carregue estes leads e coloque-os na campanha de outubro».",
  "Conectar un agente": "Conectar um agente",
  "Crea una clave de API": "Crie uma chave de API",
  "Una por sistema (por ejemplo, «CRM interno» y «Zapier»), así puedes revocar una sin cortar las demás.": "Uma por sistema (por exemplo, «CRM interno» e «Zapier»), assim você pode revogar uma sem derrubar as outras.",
  "Pásale a tu equipo técnico el mensaje de abajo": "Passe para sua equipe técnica a mensagem abaixo",
  "Con la documentación y las URLs. La clave, por un canal seguro.": "Com a documentação e as URLs. A chave, por um canal seguro.",
  "Si tu CRM debe enterarse de lo que pasa aquí, registra un webhook": "Se o seu CRM precisa saber o que acontece aqui, registre um webhook",
  "Opcional. Si no puede recibirlos, puede consultar los eventos cada pocos minutos.": "Opcional. Se ele não puder recebê-los, pode consultar os eventos a cada poucos minutos.",
  "Verifica que funciona": "Verifique se funciona",
  "Cuando tu sistema haga su primera llamada, la verás en Registro.": "Quando seu sistema fizer a primeira chamada, você a verá em Registro.",
