  "Aún no hay entregas. Aparecen aquí en cuanto ocurre un evento al que un webhook está suscrito.": "Ainda não há entregas. Elas aparecem aqui assim que ocorre um evento em que um webhook está inscrito.",
  "Reemplaza <TU_CLAVE> por una clave de la pestaña Claves de API (si acabas de crear una en esta sesión, aparece ya puesta).": "Substitua <TU_CLAVE> por uma chave da aba Chaves de API (se você acabou de criar uma nesta sessão, ela já aparece preenchida).",
  "Pega esto en tu terminal:": "Cole isto no seu terminal:",
  "Cursor, Windsurf, VS Code y clientes con archivo de configuración": "Cursor, Windsurf, VS Code e clientes com arquivo de configuração",
  "Agrégalo al archivo de servidores MCP (en Cursor: Settings → MCP → Add new server):": "Adicione ao arquivo de servidores MCP (no Cursor: Settings → MCP → Add new server):",
  "Claude, ChatGPT y clientes que solo aceptan una URL": "Claude, ChatGPT e clientes que só aceitam uma URL",
  "En «Conectores» → «Agregar conector personalizado», pega esta URL. La clave queda dentro de la URL: usa una de solo lectura si puedes y revócala si la compartes por error.": "Em «Conectores» → «Adicionar conector personalizado», cole esta URL. A chave fica dentro da URL: use uma somente leitura se puder e revogue-a se compartilhá-la por engano.",
  "Todavía no hubo ninguna llamada. Cuando tu sistema se conecte, la verás aquí.": "Ainda não houve nenhuma chamada. Quando seu sistema se conectar, você a verá aqui.",
  "Aún no hay eventos.": "Ainda não há eventos.",
  "No se pudo cargar openapi.json ({0})": "Não foi possível carregar openapi.json ({0})",
  "Parámetro": "Parâmetro",
  "Dónde": "Onde",
  "Descripción": "Descrição",
  "En Predictable, entra a": "No Predictable, acesse",
  "Desarrolladores → Claves de API": "Desenvolvedores → Chaves de API",
  "y crea una clave. Se muestra una sola vez: guárdala en un gestor de secretos, nunca en el código ni en el navegador.": "e crie uma chave. Ela é exibida uma única vez: guarde-a em um gerenciador de segredos, nunca no código nem no navegador.",
  "Prueba la conexión con": "Teste a conexão com",
  "Carga tus contactos con": "Carregue seus contatos com",
  "= el id de tu CRM, para que reenviar el mismo registro lo actualice en vez de duplicarlo.": "= o id do seu CRM, para que reenviar o mesmo registro o atualize em vez de duplicá-lo.",
  "Registra un webhook para enterarte al instante de respuestas, cambios de estado, señales y reuniones.": "Registre um webhook para saber na hora de respostas, mudanças de status, sinais e reuniões.",
