  "Tu Predictable": "Seu Predictable",
  "Entrena la IA con la forma de vender de tu empresa": "Treine a IA com o jeito de vender da sua empresa",
  "Cada empresa vende distinto. Lo que configures aquí lo aplican el Meeting Coach, los mensajes de tus campañas, el diseño de cadencias con IA y el botón «Redactar con IA» de la Bandeja. Nada se inventa: la IA solo usa lo que tú le das y lo que ya está en tu Contexto.": "Cada empresa vende de um jeito. O que você configurar aqui é aplicado pelo Meeting Coach, pelas mensagens das suas campanhas, pelo desenho de cadências com IA e pelo botão «Escrever com IA» da Caixa de entrada. Nada é inventado: a IA só usa o que você fornece e o que já está no seu Contexto.",
  "Ver lo que sabe tu IA": "Ver o que sua IA sabe",
  "Sin metodologías para el coach, sigue con Neuroventas (la doctrina de siempre). Los principios de cada libro están resumidos con palabras propias: para entrenar con el texto de un libro que tengas, súbelo en la Base de conocimiento.": "Sem metodologias para o coach, ele segue com Neurovendas (a doutrina de sempre). Os princípios de cada livro estão resumidos com palavras próprias: para treinar com o texto de um livro que você tenha, envie-o na Base de conhecimento.",
