  "Ir a Miembros": "Ir para Membros",
  "El ranking se ordena por resultados: reuniones, respuestas o sus tasas. Los envíos se muestran como contexto y no suman puntos. Las tasas se miden sobre las personas a las que se les escribió por primera vez en el período (sus respuestas y reuniones cuentan aunque lleguen después), y con menos de {0} personas no compiten. Las diferencias son contra el mismo tramo de {1}.": "O ranking é ordenado por resultados: reuniões, respostas ou suas taxas. Os envios aparecem como contexto e não somam pontos. As taxas são medidas sobre as pessoas que receberam a primeira mensagem no período (suas respostas e reuniões contam mesmo que cheguem depois), e com menos de {0} pessoas não competem. As diferenças são em relação ao mesmo trecho de {1}.",
