  "Semana a semana desde su fecha de inicio, contra la mediana de sus compañeros en esa misma semana de antigüedad. Solo cuentan las semanas que cada compañero ya cumplió, y la mediana necesita al menos {0} compañeros.": "Semana a semana desde a data de início, em comparação com a mediana dos colegas na mesma semana de casa. Só contam as semanas que cada colega já completou, e a mediana precisa de pelo menos {0} colegas.",
