  "Escribe el nombre visible de tu negocio: Meta lo revisa antes de dejarte enviar": "Digite o nome de exibição da sua empresa: a Meta o analisa antes de liberar os envios",
  "Sigues usando la app del celular como siempre: lo que escribes ahí también aparece en la Bandeja. Tus chats de los últimos meses llegan solos en las próximas horas.": "Você continua usando o app do celular como sempre: o que você escreve lá também aparece na Caixa de entrada. Suas conversas dos últimos meses chegam sozinhas nas próximas horas.",
  "Los mensajes los cobra Meta directamente a tu tarjeta (la agregas en WhatsApp Manager → Pagos). Predictable no cobra extra por conectar.": "As mensagens são cobradas pela Meta diretamente no seu cartão (você o adiciona no WhatsApp Manager → Pagamentos). O Predictable não cobra nada a mais pela conexão.",
