  "Celular, fijo o conmutador según el plan de numeración de cada país (el mismo tipo que guarda el enriquecimiento); «sin WhatsApp» = WhatsApp ya rechazó un envío a ese número (#131026). Por confirmar = el número no lo dice (p. ej. México): se envía igual.": "Celular, fixo ou PABX conforme o plano de numeração de cada país (o mesmo tipo que o enriquecimento salva); «sem WhatsApp» = o WhatsApp já recusou um envio para esse número (#131026). A confirmar = o número não indica (p. ex. México): o envio é feito mesmo assim.",
