  "Si Apollo no lo encuentra, se busca en cascada{0}. Se cobra solo lo que se encuentra{1}, también con tu propio Apollo.": "Se o Apollo não encontrar, a busca segue em cascata{0}. Só é cobrado o que for encontrado{1}, também com o seu próprio Apollo.",
