  "Se buscará {0} vía Apollo. Costo en Apollo: 8 créditos por teléfono y 2 por email, solo cuando Apollo lo encuentra (con tu propia cuenta de Apollo conectada no gastas créditos de predictable.ai). Corre en segundo plano — puedes seguir usando la app; los resultados aparecen solos en la tabla.": "Vamos buscar {0} via Apollo. Custo no Apollo: 8 créditos por telefone e 2 por e-mail, só quando o Apollo encontra (com a sua própria conta do Apollo conectada, você não gasta créditos do predictable.ai). Roda em segundo plano — você pode continuar usando o app; os resultados aparecem sozinhos na tabela.",
