  "Se cuentan identificadores (emails, teléfonos, dominios y perfiles), no personas: la baja de un lead suprime cada dato suyo.{0}": "Contamos identificadores (e-mails, telefones, domínios e perfis), não pessoas: o descadastro de um lead suprime cada dado dele.{0}",
  "(el registro se actualiza cada {0} días)": "(o registro é atualizado a cada {0} dias)",
  "Vigente hasta{0}": "Válido até{0}",
  "Hasta {0} números se guarda el archivo completo. Si es más grande, se cruza en tu navegador con los teléfonos de tus contactos y solo se guardan los que coinciden: los contactos que agregues después no quedan cruzados hasta la próxima importación. La importación nueva de un registro reemplaza a la anterior.": "Até {0} números, o arquivo completo é salvo. Se for maior, ele é cruzado no seu navegador com os telefones dos seus contatos e só os que coincidem são salvos: os contatos que você adicionar depois não ficam cruzados até a próxima importação. A nova importação de um registro substitui a anterior.",
