  "Tu empresa crea su cuenta de proveedor en repep.profeco.gob.mx, compra las listas de su región y descarga el archivo. PROFECO actualiza las listas cada 15 días.": "Sua empresa cria a conta de fornecedor em repep.profeco.gob.mx, compra as listas da sua região e baixa o arquivo. A PROFECO atualiza as listas a cada 15 dias.",
  "Tu empresa se registra en el portal de trámites de la CRC y consulta sus números (uno a uno, masiva de hasta 10.000 o web service). Sube aquí los números que salieron excluidos. La CRC indica consultar antes de cada contacto.": "Sua empresa se cadastra no portal de serviços da CRC e consulta os números (um por um, em massa até 10.000 ou via web service). Envie aqui os números que saíram como excluídos. A CRC orienta consultar antes de cada contato.",
  "Tu empresa consulta con la API de la AAIP (con sus credenciales) o en nollame.aaip.gob.ar. Sube aquí los números inscritos. La AAIP indica consultar al menos cada 30 días.": "Sua empresa consulta pela API da AAIP (com as credenciais dela) ou em nollame.aaip.gob.ar. Envie aqui os números inscritos. A AAIP orienta consultar pelo menos a cada 30 dias.",
  "En el Portal del Proveedor del SERNAC tu empresa ve las solicitudes «No Molestar» que la nombran. Sube aquí esos números. Según el SERNAC, la solicitud rige desde que se hace.": "No Portal do Fornecedor do SERNAC, sua empresa vê as solicitações «No Molestar» que a mencionam. Envie aqui esses números. Segundo o SERNAC, a solicitação vale desde o momento em que é feita.",
  "Tu empresa se registra en el Procon-SP para acceder a la lista de bloqueo de telemarketing y descarga el archivo. Según el Procon-SP, un número no se llama desde el día 30 de su inscripción.": "Sua empresa se cadastra no Procon-SP para acessar a lista de bloqueio de telemarketing e baixa o arquivo. Segundo o Procon-SP, um número não pode receber ligações a partir do 30º dia da inscrição.",
  "La lista de supresión todavía no está activada en la base de datos (falta aplicar la migración 20261017000004_suppression.sql).": "A lista de supressão ainda não está ativada no banco de dados (falta aplicar a migração 20261017000004_suppression.sql).",
