  "Ver más": "Ver mais",
  "A estos contactos Predictable no les escribe ni les llama. Antes de cada envío, la campaña revisa esta lista: si el lead está suprimido en ese canal, el paso se omite con el motivo y sigue con el siguiente. Cuando un lead pide la baja por cualquier canal, se suprimen todos sus datos en todos los canales.": "O Predictable não escreve nem liga para estes contatos. Antes de cada envio, a campanha consulta esta lista: se o lead estiver suprimido nesse canal, a etapa é ignorada com o motivo e segue para a próxima. Quando um lead pede o descadastro por qualquer canal, todos os dados dele são suprimidos em todos os canais.",
