  "Todavía no tienes un sitio conectado.": "Você ainda não tem um site conectado.",
  "Crea tu widget en la pestaña «Sitios», pega el código en tu web y cada formulario o clic de WhatsApp llega aquí con su cronómetro.": "Crie seu widget na aba «Sites», cole o código no seu site e cada formulário ou clique no WhatsApp chega aqui com o cronômetro.",
  "Crear mi widget": "Criar meu widget",
  "Últimos {0} días": "Últimos {0} dias",
  "Sin leads inbound en este período. Cuando lleguen verás aquí cuánto tarda cada SDR en hacer el primer contacto.": "Nenhum lead inbound neste período. Quando chegarem, você verá aqui quanto tempo cada SDR leva para fazer o primeiro contato.",
  "Contactados en ≤ {0} min": "Contatados em ≤ {0} min",
  "≤ {0} min": "≤ {0} min",
  "Pendientes": "Pendentes",
  "El primer contacto es el primer mensaje que sale al lead desde la Bandeja o una campaña (cualquier canal), o «Ya lo contacté». La respuesta automática del sitio no cuenta: es la máquina, no el SDR. El % en ≤ {0} min es sobre todos los leads del período, contactados o no.": "O primeiro contato é a primeira mensagem enviada ao lead pela Caixa de entrada ou por uma campanha (qualquer canal), ou «Já entrei em contato». A resposta automática do site não conta: é a máquina, não o SDR. O % em ≤ {0} min é sobre todos os leads do período, contatados ou não.",
  "{0} es responsable del tratamiento de los datos personales que nos compartes en este formulario: nombre, email, teléfono o WhatsApp, empresa, cargo y el mensaje que escribas, además de la página desde la que nos escribes.": "{0} é responsável pelo tratamento dos dados pessoais que você compartilha neste formulário: nome, e-mail, telefone ou WhatsApp, empresa, cargo e a mensagem que você escrever, além da página de onde você nos escreve.",
  "Puedes pedirnos en cualquier momento acceder a tus datos, corregirlos, eliminarlos u oponerte a su uso, o retirar tu consentimiento, escribiendo a {0}. Si nos escribes por WhatsApp, también puedes responder «BAJA» para que no te volvamos a escribir.": "Você pode nos pedir a qualquer momento para acessar, corrigir ou excluir seus dados, se opor ao uso deles ou retirar seu consentimento, escrevendo para {0}. Se você nos escrever pelo WhatsApp, também pode responder «SAIR» para não receber mais mensagens.",
  "{0} · lista «{1}»": "{0} · lista «{1}»",
  "Últimos 30 días: {0} envíos · {1} clics directos a WhatsApp · {2} bloqueados por spam · {3} leads (90 días)": "Últimos 30 dias: {0} envios · {1} cliques diretos no WhatsApp · {2} bloqueados por spam · {3} leads (90 dias)",
  "El widget": "O widget",
  "Campos del formulario": "Campos do formulário",
  "El nombre siempre se pide. Mientras más corto, más leads: email o WhatsApp, empresa y listo.": "O nome é sempre solicitado. Quanto mais curto, mais leads: e-mail ou WhatsApp, empresa e pronto.",
  "Privacidad y consentimiento": "Privacidade e consentimento",
  "El aviso sugerido es un punto de partida para Latam; revísalo con tu asesor legal. Cada envío guarda el texto exacto que aceptó el visitante, la hora y la página.": "O aviso sugerido é um ponto de partida para a América Latina; revise-o com seu assessor jurídico. Cada envio guarda o texto exato que o visitante aceitou, o horário e a página.",
  "Usar el aviso sugerido": "Usar o aviso sugerido",
  "({0} créditos si encuentra el email, con la cuenta de Apollo compartida)": "({0} créditos se encontrar o e-mail, com a conta compartilhada do Apollo)",
  "Enriquecer con Apollo al llegar{0}": "Enriquecer com o Apollo na chegada{0}",
  "({0} créditos por lead)": "({0} créditos por lead)",
  "Investigar con IA al llegar: verifica el cargo e investiga la empresa{0}": "Pesquisar com IA na chegada: verifica o cargo e pesquisa a empresa{0}",
  "Al llegar un lead": "Quando um lead chegar",
  "Los créditos se descuentan de la cuenta de quien recibe el lead. Sin saldo, el lead entra igual, sin enriquecer.": "Os créditos são descontados da conta de quem recebe o lead. Sem saldo, o lead entra mesmo assim, sem enriquecimento.",
  "Tamaños: {0}. Países en inglés, como en tu ICP (Mexico, Colombia, Brazil…).": "Portes: {0}. Países em inglês, como no seu ICP (Mexico, Colombia, Brazil…).",
  "Pega el código en tu sitio (antes de </body>). Funciona en WordPress, Wix, Shopify, Webflow o HTML propio.": "Cole o código no seu site (antes de </body>). Funciona em WordPress, Wix, Shopify, Webflow ou HTML próprio.",
  "Nuevo sitio": "Novo site",
  "{0} tu primer contacto.": "{0} o seu primeiro contato.",
  "Cada lead de tu web, contactado en minutos": "Cada lead do seu site, contatado em minutos",
  "Un botón de WhatsApp y un formulario corto para tu sitio. Cada lead llega a la lista del SDR que le toca, con su página de origen, sus UTM y el consentimiento registrado, y un cronómetro corre hasta el primer contacto.": "Um botão de WhatsApp e um formulário curto para o seu site. Cada lead chega à lista do SDR responsável, com a página de origem, as UTMs e o consentimento registrado, e um cronômetro corre até o primeiro contato.",
  "{0} tu primer contacto": "{0} o seu primeiro contato",
  "Acepto que mis datos se usen para contactarme por WhatsApp, teléfono o email sobre mi solicitud, según el aviso de privacidad.": "Aceito que meus dados sejam usados para entrar em contato comigo por WhatsApp, telefone ou e-mail sobre a minha solicitação, conforme o aviso de privacidade.",
