  "Aviso de privacidad": "Aviso de privacidade",
  "Los usamos solo para responder a tu solicitud y contactarte por WhatsApp, teléfono o email sobre nuestros productos y servicios. No los vendemos ni los compartimos con terceros, salvo con los proveedores que nos ayudan a operar (alojamiento, mensajería y CRM), que los tratan por cuenta nuestra.": "Usamos seus dados apenas para responder à sua solicitação e entrar em contato por WhatsApp, telefone ou e-mail sobre nossos produtos e serviços. Não os vendemos nem compartilhamos com terceiros, exceto com os fornecedores que nos ajudam a operar (hospedagem, mensageria e CRM), que os tratam em nosso nome.",
  "Tratamos tus datos conforme a la ley de protección de datos de tu país (por ejemplo, la LFPDPPP en México, la Ley 1581 de 2012 en Colombia, la LGPD en Brasil, la Ley 25.326 en Argentina, la Ley 19.628 en Chile y la Ley 29733 en Perú).": "Tratamos seus dados conforme a lei de proteção de dados do seu país (por exemplo, a LGPD no Brasil, a LFPDPPP no México, a Lei 1581 de 2012 na Colômbia, a Lei 25.326 na Argentina, a Lei 19.628 no Chile e a Lei 29733 no Peru).",
