  "Sale por el WhatsApp de quien recibe el lead. No cuenta como primer contacto.": "Sai pelo WhatsApp de quem recebe o lead. Não conta como primeiro contato.",
  "Enrutamiento": "Roteamento",
  "Para repartir leads, primero arma la nómina de tu equipo en «Equipo». Solo se reparte a personas de esa nómina.": "Para distribuir leads, primeiro monte a lista da sua equipe em «Equipe». Só são distribuídos para pessoas dessa lista.",
  "Los leads de este sitio llegan a ti. Repartirlos entre el equipo lo configura un administrador o director.": "Os leads deste site chegam para você. A distribuição entre a equipe é configurada por um administrador ou diretor.",
