  "Round robin entre las personas elegidas": "Round robin entre as pessoas escolhidas",
  "Reglas (van antes que el reparto, la primera que coincide gana). El país sale del formulario o del código del WhatsApp.": "Regras (vêm antes da distribuição; a primeira que corresponder vence). O país vem do formulário ou do código do WhatsApp.",
  "+ Agregar regla": "+ Adicionar regra",
  "Vista previa": "Pré-visualização",
  "Aún no creaste ningún widget. Con «Nuevo sitio» configuras el formulario, el botón de WhatsApp, el aviso de privacidad y a quién le llegan los leads.": "Você ainda não criou nenhum widget. Em «Novo site» você configura o formulário, o botão de WhatsApp, o aviso de privacidade e quem recebe os leads.",
  "Ponle un nombre al sitio.": "Dê um nome ao site.",
  "Escribe el WhatsApp de tu equipo con código de país, o elige «Solo formulario».": "Informe o WhatsApp da sua equipe com código do país, ou escolha «Só formulário».",
  "Elige al menos una persona para el round robin.": "Escolha pelo menos uma pessoa para o round robin.",
  "Sitio guardado. El widget toma los cambios en un minuto.": "Site salvo. O widget recebe as alterações em um minuto.",
  "Sitio creado. Copia el código y pégalo en tu web.": "Site criado. Copie o código e cole no seu site.",
  "¿Eliminar este sitio? El widget deja de funcionar en tu web y se borran sus leads inbound (los contactos de tus Listas se quedan).": "Excluir este site? O widget deixa de funcionar no seu site e os leads inbound dele são excluídos (os contatos das suas Listas permanecem).",
  "Así se ve el formulario con lo último que guardaste (los envíos desde aquí son reales y llegan a tus leads).": "Assim fica o formulário com o que você salvou por último (os envios feitos daqui são reais e chegam aos seus leads).",
