  "Sitios": "Sites",
  "Copia este código:": "Copie este código:",
  "Tus champions cambian de empresa": "Seus champions mudam de empresa",
  "Champion en seguimiento: el Radar te avisa si cambia de empresa. Clic para dejar de seguirlo.": "Champion em acompanhamento: o Radar avisa você se ele mudar de empresa. Clique para deixar de acompanhar.",
  "Sugerido como champion (tuvo una reunión). Clic para seguirlo.": "Sugerido como champion (teve uma reunião). Clique para acompanhar.",
  "Marcar como champion: el Radar te avisa si cambia de empresa.": "Marcar como champion: o Radar avisa você se ele mudar de empresa.",
  "Dejaste de seguirlo como champion.": "Você deixou de acompanhá-lo como champion.",
  "Champion en seguimiento: el Radar te avisa si cambia de empresa.": "Champion em acompanhamento: o Radar avisa você se ele mudar de empresa.",
  "Para seguirlo como champion necesita nombre y empresa: agrégalos con «Editar contacto».": "Para acompanhá-lo como champion, é preciso ter nome e empresa: adicione-os em «Editar contato».",
  "esa persona ya está en tu lista de champions.": "essa pessoa já está na sua lista de champions.",
  "Champion en seguimiento: el Radar te avisa si cambia de empresa (pestaña Champions).": "Champion em acompanhamento: o Radar avisa você se ele mudar de empresa (aba Champions).",
  "¿Dejar de seguir a {0}? Se borra de la lista de champions (el lead de tu lista no se toca).": "Deixar de acompanhar {0}? A pessoa sai da lista de champions (o lead da sua lista não é alterado).",
  "{0} quedó en seguimiento.{1}": "{0} agora está em acompanhamento.{1}",
  "Un mensaje para retomar la relación en su empresa nueva, con la historia real (mensajes, reuniones, notas) y tu entrenamiento IA. Nunca se envía solo.": "Uma mensagem para retomar o relacionamento na nova empresa, com o histórico real (mensagens, reuniões, notas) e o seu treinamento da IA. Nunca é enviada automaticamente.",
  "Usa la historia real con esta persona. Nunca se envía solo.": "Usa o histórico real com esta pessoa. Nunca é enviada automaticamente.",
  "Envíalo desde tu canal o enrólala en una campaña desde Listas.": "Envie pelo seu canal ou inscreva a pessoa em uma campanha a partir de Listas.",
  "Cuando alguien que ya te compró o te respondió bien se muda a otra empresa, esa empresa es la reunión más cálida que vas a conseguir. El Radar chequea a tus champions con Apollo (y, si Apollo no los ubica, con una búsqueda web pública) y te avisa con la señal «Tu champion se mudó a…». No se lee LinkedIn por API ni se scrapea.": "Quando alguém que já comprou de você ou respondeu bem muda de empresa, essa empresa é a reunião mais calorosa que você vai conseguir. O Radar verifica seus champions com o Apollo (e, se o Apollo não os localizar, com uma busca pública na web) e avisa você com o sinal «Seu champion mudou para…». O LinkedIn não é lido por API nem raspado.",
  "Activar seguimiento": "Ativar acompanhamento",
  "Corre como un detector de personas (10 créditos cada 30 días). Con la cuenta de Apollo de la plataforma, cada persona encontrada cuesta 2 créditos; con tu propio Apollo, lo paga tu cuenta.": "Funciona como um detector de pessoas (10 créditos a cada 30 dias). Com a conta do Apollo da plataforma, cada pessoa encontrada custa 2 créditos; com o seu próprio Apollo, quem paga é a sua conta.",
