  "Sin alerta": "Sem alerta",
  "El tope cuenta el mes calendario: al llegar a él, las acciones que cobran créditos se frenan en ese espacio hasta el mes siguiente. Vacío = sin tope.": "O limite considera o mês calendário: ao atingi-lo, as ações que cobram créditos ficam bloqueadas nesse espaço até o mês seguinte. Vazio = sem limite.",
