  "Ningún espacio gastó créditos entre el {0} y el {1}.": "Nenhum espaço gastou créditos entre {0} e {1}.",
  "Créditos netos: lo gastado menos lo que se devolvió (por ejemplo, un email que Apollo no encontró). Los repartos entre tu cuenta y los espacios no cuentan como consumo. Las fechas van en tu hora local.": "Créditos líquidos: o que foi gasto menos o que foi devolvido (por exemplo, um e-mail que o Apollo não encontrou). As distribuições entre a sua conta e os espaços não contam como consumo. As datas estão no seu horário local.",
