  "Qué hace tu agencia (opcional, se muestra en el directorio)": "O que a sua agência faz (opcional, aparece no diretório)",
  "Mostrar en el directorio público de agencias": "Mostrar no diretório público de agências",
  "Ver el directorio": "Ver o diretório",
  "Créditos por espacio": "Créditos por espaço",
  "Compras una vez en tu cuenta y repartes a cada cliente. Lo que asignas sale primero de la bolsa de tu plan y vence con ella; las recargas no vencen. Si borras un cliente, su saldo vuelve a tu cuenta.": "Você compra uma vez na sua conta e distribui para cada cliente. O que você atribui sai primeiro do pacote do seu plano e vence com ele; as recargas não vencem. Se você excluir um cliente, o saldo dele volta para a sua conta.",
  "Créditos que gastó cada espacio por función, para refacturar a tus clientes.": "Créditos que cada espaço gastou por recurso, para você repassar a cobrança aos seus clientes.",
  "Predictable para agencias": "Predictable para agências",
  "Si gestionas la prospección de varios clientes, cada uno puede tener su propio Predictable (Contexto, Radar, Listas, Campañas) dentro de tu cuenta: tú compras los créditos y los repartes, y ves cuánto gastó cada cliente para refacturarle. Envía la ficha de tu agencia; la aprobamos a mano.": "Se você cuida da prospecção de vários clientes, cada um pode ter o próprio Predictable (Contexto, Radar, Listas, Campanhas) dentro da sua conta: você compra os créditos, distribui e vê quanto cada cliente gastou para repassar a cobrança. Envie o perfil da sua agência; a aprovação é manual.",
  "Ficha de tu agencia": "Perfil da sua agência",
  "Es la que aparece en el directorio público de agencias. Solo se publica cuando la aprobamos.": "É o que aparece no diretório público de agências. Só é publicado depois da nossa aprovação.",
