  "Para abrir espacios de clientes tu agencia necesita, además de la ficha aprobada, un plan": "Para abrir espaços de clientes, além do perfil aprovado, sua agência precisa de um plano",
  "activo. Puedes enviar la ficha antes.": "ativo. Você pode enviar o perfil antes.",
  "Tu ficha ya fue revisada. Para cambiar nombre, sitio, países o verticales escríbenos y la revisamos de nuevo. Mostrarla u ocultarla del directorio lo decides tú.": "Seu perfil já foi revisado. Para alterar nome, site, países ou verticais, fale com a gente e revisaremos novamente. Mostrar ou ocultar no diretório é decisão sua.",
  "Guardar ficha": "Salvar perfil",
  "Estás dentro del espacio de un cliente. Los créditos y el consumo de tus clientes se gestionan desde tu cuenta: usa «Volver a mi cuenta».": "Você está dentro do espaço de um cliente. Os créditos e o consumo dos seus clientes são gerenciados na sua conta: use «Voltar para minha conta».",
