  "El agente devuelve llamadas, confirma o reprograma reuniones y califica a quien ya mostró interés.": "O agente retorna ligações, confirma ou reagenda reuniões e qualifica quem já demonstrou interesse.",
  "Nunca llama en frío": "Nunca faz ligações frias",
  ", siempre dice que es un asistente con IA y ofrece pasar con una persona.": ", sempre se apresenta como assistente com IA e oferece transferir para uma pessoa.",
  "Activar el agente de voz": "Ativar o agente de voz",
  "Nombre del asistente": "Nome do assistente",
  "Número para pasar con una persona (opcional)": "Número para transferir para uma pessoa (opcional)",
  "Si lo dejas vacío, cuando el lead pida una persona el agente acuerda que alguien del equipo lo llame.": "Se ficar vazio, quando o lead pedir para falar com uma pessoa, o agente combina que alguém da equipe vai ligar para ele.",
  "Duración máxima de cada llamada": "Duração máxima de cada ligação",
  "Grabar el audio de las llamadas": "Gravar o áudio das ligações",
  "Siempre se transcribe y el agente lo avisa al inicio. Si grabas, el agente también avisa que la llamada se graba y, si el lead no acepta, se borra el audio. Sin grabación, el audio se borra del proveedor apenas guardamos la transcripción.": "A ligação é sempre transcrita e o agente avisa no início. Se você gravar, o agente também avisa que a ligação está sendo gravada e, se o lead não aceitar, o áudio é excluído. Sem gravação, o áudio é excluído do provedor assim que salvamos a transcrição.",
  "Lo que exige cada país": "O que cada país exige",
  "Resumen orientativo, no es asesoría legal: revisa con tu abogado antes de grabar.": "Resumo orientativo, não é assessoria jurídica: consulte seu advogado antes de gravar.",
  "Costo: {0} créditos por minuto conectado ({1} a Argentina). Si no contesta, no cuesta.": "Custo: {0} créditos por minuto conectado ({1} para a Argentina). Se não atender, não custa nada.",
  "¿Para qué es la llamada?": "Qual é o objetivo da ligação?",
  "El lead me pidió que lo llamáramos (fuera de la Bandeja)": "O lead pediu para ligarmos para ele (fora da Caixa de entrada)",
