  "El agente de voz todavía no está activado en el servidor (falta aplicar la migración).": "O agente de voz ainda não está ativado no servidor (falta aplicar a migração).",
  "En llamada…": "Em ligação…",
  "Llamando…": "Ligando…",
  "Se movió el evento en tu Google Calendar.": "O evento foi movido no seu Google Calendar.",
  "Se anotó la confirmación en tu Google Calendar.": "A confirmação foi registrada no seu Google Calendar.",
  "Sin llamadas todavía. El agente llama solo a quien pidió que lo llamaran, tiene una reunión o ya mostró interés: se presenta como asistente con IA, ofrece pasar con una persona y deja aquí la transcripción, el resumen y el siguiente paso. Se cobra por minuto conectado; si no contesta, no cuesta.": "Nenhuma ligação ainda. O agente só liga para quem pediu uma ligação, tem uma reunião ou já demonstrou interesse: ele se apresenta como assistente com IA, oferece transferir para uma pessoa e deixa aqui a transcrição, o resumo e o próximo passo. A cobrança é por minuto conectado; se não atender, não custa nada.",
  "El proveedor de voz todavía no está activado en la plataforma: puedes dejar esto listo, pero no se podrá llamar hasta que lo esté.": "O provedor de voz ainda não está ativado na plataforma: você pode deixar tudo pronto, mas só será possível ligar depois que ele estiver ativo.",
  "El número para pasar con una persona debe ir con el prefijo del país (por ejemplo +52…).": "O número para transferir para uma pessoa deve ter o código do país (por exemplo, +55…).",
