  "Revisado contra tu lista «No contactar» (bajas y registros «No llamar» que cargaste en Campañas → Bajas y exclusiones).": "Verificado na sua lista «Não contatar» (descadastros e registros «Não ligar» que você carregou em Campanhas → Descadastros e exclusões).",
