  "puntaje ≥ {0}": "pontuação ≥ {0}",
  "Cuando pase algo, Predictable hace el siguiente paso": "Quando algo acontecer, o Predictable faz a próxima etapa",
  "Reglas sin código que encadenan el Radar, tus listas, el enriquecimiento, la investigación con IA y tus campañas. Lo que gasta créditos o envía mensajes espera tu aprobación, con el costo a la vista; cuando confíes en una regla, pásala a automática con un tope diario.": "Regras sem código que conectam o Radar, suas listas, o enriquecimento, a pesquisa com IA e suas campanhas. O que gasta créditos ou envia mensagens aguarda a sua aprovação, com o custo à vista; quando você confiar em uma regra, mude-a para automática com um limite diário.",
