  "¿Aprobar {0} ejecuciones? Pueden costar hasta {1} créditos.": "Aprovar {0} execuções? Elas podem custar até {1} créditos.",
  "Cuando el Radar te entrega una señal (el lote diario de «Nuevas»).": "Quando o Radar entrega um sinal para você (o lote diário de «Novos»).",
  "Lead nuevo en una lista": "Lead novo em uma lista",
  "Cuando entra un lead a una lista (desde Buscar, el Radar, una importación o a mano).": "Quando um lead entra em uma lista (pelo Buscar, pelo Radar, por importação ou manualmente).",
  "Respuesta en la Bandeja": "Resposta na Caixa de entrada",
  "Cuando un lead responde. Positiva o negativa se decide por frases claras («me interesa», «agendemos», «no me interesa», «darme de baja»…); una respuesta dudosa no dispara nada.": "Quando um lead responde. Positiva ou negativa é decidido por frases claras («tenho interesse», «vamos agendar», «não tenho interesse», «quero me descadastrar»…); uma resposta ambígua não aciona nada.",
  "Campaña terminada sin respuesta": "Campanha concluída sem resposta",
  "Cuando un lead recorre toda la cadencia de una campaña y no respondió.": "Quando um lead percorre toda a cadência de uma campanha e não respondeu.",
  "Cuando marcas a un lead como «Reunión conseguida» (en Listas o en la Bandeja).": "Quando você marca um lead como «Reunião conseguida» (em Listas ou na Caixa de entrada).",
  "Cuando el lead pasa a «Reunión tomada» (también al cerrar la reunión en el Meeting Coach).": "Quando o lead passa para «Reunião realizada» (também ao encerrar a reunião no Meeting Coach).",
  "Buscar decisores de la empresa": "Buscar decisores da empresa",
  "Toma los decisores de la señal (o los busca en Apollo) y elige los que coinciden con el cargo y la seniority de tu ICP. Los guarda en una lista y revela su email.": "Pega os decisores do sinal (ou os busca no Apollo) e escolhe os que correspondem ao cargo e à senioridade do seu ICP. Salva-os em uma lista e revela o e-mail deles.",
  "Agregar a una lista": "Adicionar a uma lista",
  "Copia los leads a otra lista (sin duplicar).": "Copia os leads para outra lista (sem duplicar).",
  "Email personal y, si quieres, teléfono. Corre en el servidor como «Enriquecer seleccionados».": "E-mail pessoal e, se quiser, telefone. Roda no servidor como «Enriquecer selecionados».",
  "Verifica que sigan en la empresa, investiga la empresa y propone el ángulo. Una investigación de menos de 30 días no se vuelve a pagar.": "Verifica se continuam na empresa, pesquisa a empresa e propõe o ângulo. Uma pesquisa com menos de 30 dias não é cobrada de novo.",
  "Enrolar en una campaña": "Inscrever em uma campanha",
  "Los enrola en una campaña activa. La campaña envía los mensajes.": "Inscreve os leads em uma campanha ativa. A campanha envia as mensagens.",
  "Crear una tarea": "Criar uma tarefa",
  "Una tarea por lead en CRM → Tareas. Usa {nombre}, {empresa} y {senal} en el título.": "Uma tarefa por lead em CRM → Tarefas. Use {nombre}, {empresa} e {senal} no título.",
  "Avisarme": "Me avisar",
  "Aviso por push (si activaste las notificaciones) y/o por WhatsApp al número de Radar → Avisos.": "Alerta por push (se você ativou as notificações) e/ou por WhatsApp no número de Radar → Alertas.",
  "Señal fuerte → 3 decisores → enriquecer → investigar → campaña": "Sinal forte → 3 decisores → enriquecer → pesquisar → campanha",
  "El momento de una señal se enfría rápido. Llega primero a los que deciden, con contexto de la empresa, sin escribir a mano. Con aprobación: tú ves el costo antes.": "O momento de um sinal esfria rápido. Chegue primeiro a quem decide, com contexto da empresa, sem escrever à mão. Com aprovação: você vê o custo antes.",
  "Señal del Radar → decisores a una lista + tarea de revisión": "Sinal do Radar → decisores em uma lista + tarefa de revisão",
  "Para revisar cada cuenta antes de escribir: los decisores quedan listos en una lista y te queda la tarea con la señal.": "Para revisar cada conta antes de escrever: os decisores ficam prontos em uma lista e você fica com a tarefa com o sinal.",
  "Lead nuevo en una lista → investigar con IA": "Lead novo em uma lista → pesquisar com IA",
  "Cada lead que entra a la lista llega a Campañas con su ángulo y su puesto verificado.": "Cada lead que entra na lista chega a Campanhas com o seu ângulo e o cargo verificado.",
  "Respuesta positiva → tarea para hoy + aviso": "Resposta positiva → tarefa para hoje + alerta",
  "La velocidad de respuesta a un lead interesado pesa más que el texto: te avisa al instante y te deja la tarea.": "A velocidade de resposta a um lead interessado pesa mais que o texto: avisa você na hora e deixa a tarefa pronta.",
  "Responder a {nombre} y proponer una reunión": "Responder a {nombre} e propor uma reunião",
  "Respuesta negativa → lista de no interesados": "Resposta negativa → lista de não interessados",
  "Separa a quien dijo que no, para no volver a escribirle desde otra campaña y revisar el motivo.": "Separa quem disse não, para não escrever de novo a partir de outra campanha e revisar o motivo.",
  "Campaña sin respuesta → lista de reciclaje + tarea de llamada": "Campanha sem resposta → lista de reciclagem + tarefa de ligação",
  "Quien no respondió por escrito puede responder a una llamada o a otra campaña más adelante.": "Quem não respondeu por escrito pode responder a uma ligação ou a outra campanha mais adiante.",
  "Reunión agendada → investigar + aviso": "Reunião agendada → pesquisar + alerta",
  "Llega a la reunión con la empresa investigada y el ángulo listo para el Meeting Coach.": "Chegue à reunião com a empresa pesquisada e o ângulo pronto para o Meeting Coach.",
  "Reunión tomada → tarea de seguimiento": "Reunião realizada → tarefa de acompanhamento",
