  "Cuando una campaña llega a un paso de llamada, la tarea aparece aquí con su guion. También puedes llamar a cualquier lead desde Listas o la Bandeja.": "Quando uma campanha chega a uma etapa de ligação, a tarefa aparece aqui com o roteiro. Você também pode ligar para qualquer lead em Listas ou na Caixa de entrada.",
