  "Todavía no hay llamadas": "Ainda não há ligações",
  "Las llamadas del dialer y de tu proveedor aparecen aquí con su resultado, grabación y transcripción.": "As ligações do discador e do seu provedor aparecem aqui com o resultado, a gravação e a transcrição.",
  "Dialer de Predictable": "Discador do Predictable",
  "Llama desde el navegador con tu micrófono, con grabación, transcripción y el Meeting Coach en vivo. Cada minuto se paga en créditos según el país.": "Ligue pelo navegador com o seu microfone, com gravação, transcrição e o Meeting Coach ao vivo. Cada minuto é pago em créditos conforme o país.",
  "Todavía no está activo en esta cuenta de Predictable. Mientras tanto puedes conectar tu proveedor abajo.": "Ainda não está ativo nesta conta do Predictable. Enquanto isso, você pode conectar o seu provedor abaixo.",
