  "¿Ya usas un proveedor de llamadas?": "Já usa um provedor de ligações?",
  "Conéctalo y llama con un clic desde Predictable: tus minutos los sigue cobrando tu proveedor, y cada llamada queda registrada aquí con su grabación.": "Conecte-o e ligue com um clique pelo Predictable: seus minutos continuam sendo cobrados pelo seu provedor, e cada ligação fica registrada aqui com a gravação.",
  "Dialer": "Discador",
  "Número sin lead": "Número sem lead",
  "Esta llamada no tiene grabación.": "Esta ligação não tem gravação.",
  "{0} sin teléfono (se omite {1})": "{0} sem telefone (ignorando {1})",
  "Guion IA": "Roteiro com IA",
  "Recomendado: un guion distinto por lead": "Recomendado: um roteiro diferente para cada lead",
  "Mi guion": "Meu roteiro",
  "Días que la cadencia espera la llamada": "Dias que a cadência aguarda a ligação",
  "Este paso crea una tarea en Campañas → Llamadas con el guion. Cuando marcas el resultado, la cadencia sigue: «Reunión agendada» y «No interesado» la detienen; «Contestó» y «Buzón» se pueden usar en una condición. Si nadie llama en ese plazo, el paso se omite. Sin teléfono, se omite.": "Esta etapa cria uma tarefa em Campanhas → Ligações com o roteiro. Quando você marca o resultado, a cadência continua: «Reunião agendada» e «Sem interesse» a interrompem; «Atendeu» e «Caixa postal» podem ser usados em uma condição. Se ninguém ligar nesse prazo, a etapa é ignorada. Sem telefone, também é ignorada.",
  "La IA escribe el guion de cada lead 24 h antes (apertura, preguntas, objeciones, cierre y mensaje de buzón) con el ángulo de ESTE paso y lo que ya se le envió. Cuesta 2 créditos por guion.": "A IA escreve o roteiro de cada lead 24 h antes (abertura, perguntas, objeções, fechamento e recado para a caixa postal) com o ângulo DESTA etapa e o que já foi enviado. Custa 2 créditos por roteiro.",
  "Hola {{nombre}}, te llamo de… ¿tienes 30 segundos?": "Olá, {{nombre}}, estou ligando da… Você tem 30 segundos?",
  "El mismo guion para todos los leads; las variables se reemplazan con los datos de cada uno en la tarea de llamar.": "O mesmo roteiro para todos os leads; as variáveis são substituídas pelos dados de cada um na tarefa de ligação.",
  "el WhatsApp y la llamada": "o WhatsApp e a ligação",
  "la llamada": "a ligação",
  "el WhatsApp": "o WhatsApp",
  "Los WhatsApp salen del número conectado; los emails, de la cuenta elegida. LinkedIn no lleva tope: el ritmo lo decide tu cuenta de LinkedIn. La ventana horaria y los días se aplican en la zona horaria indicada. A los leads de Colombia, además, solo se les envía de lunes a viernes de 7:00 a 19:00 y sábados de 8:00 a 15:00 (hora de Colombia), nunca domingos ni festivos, y un envío por día (Ley 2300).": "As mensagens de WhatsApp saem do número conectado; os e-mails, da conta escolhida. O LinkedIn não tem limite: o ritmo é definido pela sua conta do LinkedIn. A janela de horário e os dias seguem o fuso horário indicado. Para leads da Colômbia, além disso, os envios só acontecem de segunda a sexta, das 7:00 às 19:00, e aos sábados, das 8:00 às 15:00 (horário da Colômbia), nunca aos domingos e feriados, com um envio por dia (Ley 2300).",
  "{0}: una llamada no puede salir \"junto con el anterior\": la hace una persona.": "{0}: uma ligação não pode sair \"junto com a anterior\": quem faz é uma pessoa.",
