  "Estas cifras no aparecen en tu Contexto ni en tus documentos: {0}. ¿Son reales y quieres aprobar igual?": "Estes números não aparecem no seu Contexto nem nos seus documentos: {0}. Eles são reais e você quer aprovar mesmo assim?",
  "Publicación manual": "Publicação manual",
  "La publicación automática en LinkedIn todavía no está habilitada en Predictable. Prepara, aprueba y programa tus posts aquí y publícalos con «Copiar y abrir LinkedIn».": "A publicação automática no LinkedIn ainda não está habilitada no Predictable. Prepare, aprove e agende seus posts aqui e publique-os com «Copiar e abrir o LinkedIn».",
  "Conecta tu LinkedIn": "Conecte seu LinkedIn",
  "Para que Predictable publique en tu perfil a la hora que elijas. Usa el permiso oficial de LinkedIn para publicar; no lee tu perfil ni tus mensajes. Sin conectar, igual puedes copiar y publicar a mano.": "Para que o Predictable publique no seu perfil no horário que você escolher. Usa a permissão oficial do LinkedIn para publicar; não lê seu perfil nem suas mensagens. Sem conectar, você ainda pode copiar e publicar manualmente.",
  "Conectado como {0}": "Conectado como {0}",
