  "Revisa estas cifras: no aparecen en tu Contexto, tu análisis de mercado ni tus documentos —": "Revise estes números: eles não aparecem no seu Contexto, na sua análise de mercado nem nos seus documentos —",
  ". Si no son reales, bórralas antes de aprobar.": ". Se não forem reais, apague-os antes de aprovar.",
