  "Tu contenido en LinkedIn": "Seu conteúdo no LinkedIn",
  "Ideas y posts escritos con tu Contexto, tu análisis de mercado, lo que ve el Radar, lo que te funciona y tu voz entrenada. Nada sale sin tu aprobación, y la IA no inventa casos, clientes ni cifras: si no tienes prueba social cargada, el post no la menciona.": "Ideias e posts escritos com o seu Contexto, a sua análise de mercado, o que o Radar vê, o que funciona para você e a sua voz treinada. Nada sai sem a sua aprovação, e a IA não inventa casos, clientes nem números: se você não tiver prova social cadastrada, o post não a menciona.",
