  "La función de contenido todavía no está desplegada en el servidor: puedes preparar y aprobar posts, pero no generarlos con IA ni publicarlos por API.": "A função de conteúdo ainda não foi implantada no servidor: você pode preparar e aprovar posts, mas não gerá-los com IA nem publicá-los via API.",
  "Falta aplicar la migración 20261018180010_linkedin_content.sql.": "Falta aplicar a migração 20261018180010_linkedin_content.sql.",
  "1 idea nueva en tu tablero.": "1 ideia nova no seu quadro.",
  "Cambiaste el texto de un post aprobado: vuelve a borrador y tendrás que aprobarlo de nuevo. ¿Guardar?": "Você alterou o texto de um post aprovado: ele volta para rascunho e você precisará aprová-lo novamente. Salvar?",
