  "Copiamos el texto. Si LinkedIn no lo muestra, pégalo. Luego márcalo como publicado.": "Copiamos o texto. Se o LinkedIn não o mostrar, cole-o. Depois marque-o como publicado.",
  "Abrimos LinkedIn. Copia el texto desde aquí si no aparece.": "Abrimos o LinkedIn. Copie o texto daqui se ele não aparecer.",
