  "Correo de prueba enviado a {0}.": "E-mail de teste enviado para {0}.",
  "Las campañas dejan de enviar desde {0}. Lo enviado y las respuestas siguen en la Bandeja.": "As campanhas deixam de enviar a partir de {0}. O que foi enviado e as respostas continuam na Caixa de entrada.",
