  "Falta el permiso para leer deals, dueños y empresas en HubSpot. Reconecta (o agrega esos alcances a tu app privada).": "Falta a permissão para ler deals, proprietários e empresas no HubSpot. Reconecte (ou adicione esses escopos ao seu app privado).",
