  "Todavía no has invitado a ninguna empresa.": "Você ainda não convidou nenhuma empresa.",
  "Todas las cuentas de Predictable": "Todas as contas do Predictable",
  "Como equipo de predictable.ai puedes entrar a cualquier cuenta registrada sin invitación. Cada ingreso queda en el registro que la empresa ve.": "Como equipe do predictable.ai, você pode entrar em qualquer conta registrada sem convite. Cada acesso fica no registro que a empresa vê.",
  "Ninguna cuenta coincide.": "Nenhuma conta corresponde.",
  "Acceso a tu cuenta": "Acesso à sua conta",
  "Estas agencias quieren gestionar tu cuenta. Si aceptas, podrán entrar a tu cuenta y ver y operar todos tus datos (Contexto, Radar, Listas, Campañas, créditos). Puedes quitarles el acceso cuando quieras.": "Estas agências querem gerenciar sua conta. Se você aceitar, elas poderão entrar na sua conta e ver e operar todos os seus dados (Contexto, Radar, Listas, Campanhas, créditos). Você pode remover o acesso delas quando quiser.",
  "Aceptar": "Aceitar",
