  "Invitación aceptada.": "Convite aceito.",
  "Invitación rechazada.": "Convite recusado.",
  "Ver invitación": "Ver convite",
  "Una agencia te invitó a vincular tu cuenta.": "Uma agência convidou você para vincular sua conta.",
  "Estás en la cuenta de ": "Você está na conta de ",
  // Entrenamiento IA sin metodologías (2026-10-19)
  "Lo que solo sabe tu empresa: playbook, precios, casos, estilo y reglas para el Meeting Coach y tus campañas": "O que só a sua empresa sabe: playbook, preços, casos, estilo e regras para o Meeting Coach e suas campanhas",
  "Playbook o guion de ventas": "Playbook ou roteiro de vendas",
  "Tu proceso, cómo calificas, las preguntas que haces y cómo respondes a las objeciones de siempre.": "Seu processo, como você qualifica, as perguntas que faz e como responde às objeções de sempre.",
  "Planes, qué incluye cada uno, condiciones y cómo presentas el precio.": "Planos, o que cada um inclui, condições e como você apresenta o preço.",
  "Clientes reales: qué problema tenían, qué hicieron contigo y qué resultado lograron.": "Clientes reais: que problema tinham, o que fizeram com você e que resultado alcançaram.",
  "Contra quién compites, en qué ganas, en qué ganan ellos y qué dices cuando el lead los menciona.": "Contra quem você compete, onde você ganha, onde eles ganham e o que você diz quando o lead os menciona.",
  "Transcripciones de llamadas o mensajes de tu equipo que salieron bien.": "Transcrições de ligações ou mensagens da sua equipe que deram certo.",
  "Producto u otro material": "Produto ou outro material",
  "Fichas del producto, presentación comercial, preguntas frecuentes o cualquier material interno.": "Fichas do produto, apresentação comercial, perguntas frequentes ou qualquer material interno.",
  "Material de ventas": "Material de vendas",
  "1 documento de tu empresa": "1 documento da sua empresa",
  "{0} documentos de tu empresa": "{0} documentos da sua empresa",
  "Sabe:": "Sabe:",
  "Entrenado con:": "Treinado com:",
  "Todavía solo sabe lo de tu Contexto global": "Por enquanto só sabe o que está no seu Contexto global",
  "Enséñale a la IA cómo vende tu empresa": "Ensine à IA como sua empresa vende",
  "Qué vendes, a quién y contra quién ya está en tu": "O que você vende, para quem e contra quem já está no seu",
  "Contexto global": "Contexto global",
  ". Aquí suma lo que solo sabe tu equipo: tu playbook, tus precios, tus casos y cómo hablan. Lo usan el Meeting Coach, los mensajes de tus campañas, el diseño de cadencias y «Redactar con IA» de la Bandeja. Nada se inventa: la IA solo usa lo que tú le das.": ". Aqui, some o que só sua equipe sabe: seu playbook, seus preços, seus casos e como vocês falam. O Meeting Coach, as mensagens das suas campanhas, o desenho de cadências e «Redigir com IA» da Caixa de entrada usam isso. Nada é inventado: a IA só usa o que você fornece.",
  "Conocimiento de tu empresa": "Conhecimento da sua empresa",
  "Sube lo que tu equipo sabe y no está escrito en ningún otro lado: tu forma de vender, tus precios, tus casos y tu competencia. La IA lo resume en principios que puedes revisar y corregir.": "Envie o que sua equipe sabe e não está escrito em nenhum outro lugar: seu jeito de vender, seus preços, seus casos e sua concorrência. A IA resume isso em princípios que você pode revisar e corrigir.",
  "Cómo habla tu equipo": "Como sua equipe fala",
  "Cómo le escribe tu empresa a sus prospectos. Aplica a los mensajes de campaña, a las respuestas de la Bandeja y a las frases que el coach te sugiere decir.": "Como sua empresa escreve para seus prospects. Vale para as mensagens de campanha, as respostas da Caixa de entrada e as frases que o coach sugere que você diga.",
  "Reglas del equipo": "Regras da equipe",
  "Lo que tu equipo siempre hace, lo que nunca hace y cómo quieres que te hable el coach.": "O que sua equipe sempre faz, o que nunca faz e como você quer que o coach fale com você.",
  "Lo que más mejora a tu IA": "O que mais melhora sua IA",
  "{0} de {1}": "{0} de {1}",
  "PDF hasta 20 MB (unas 100 páginas). Si es largo, sube solo las partes que tu equipo usa.": "PDF de até 20 MB (cerca de 100 páginas). Se for longo, envie só as partes que sua equipe usa.",
  "Pega tu guion de llamada, tus respuestas a objeciones, tu oferta, un caso de éxito…": "Cole seu roteiro de ligação, suas respostas a objeções, sua oferta, um caso de sucesso…",
  "Todavía no subiste documentos. Empieza por lo que más usa tu equipo: tu playbook o guion de ventas.": "Você ainda não enviou documentos. Comece pelo que sua equipe mais usa: seu playbook ou roteiro de vendas.",
  "Tienes cambios sin guardar en el estilo o las reglas.": "Você tem alterações não salvas no estilo ou nas regras.",
  "Guardado. El coach y las campañas lo usan desde el próximo mensaje.": "Salvo. O coach e as campanhas usam isso a partir da próxima mensagem.",
  "Escribe un mensaje cuyo gancho es esta señal, con el estilo, las reglas y el conocimiento de tu empresa con que entrenaste la IA. Cae en el cuadro de respuesta para que lo edites; nunca se envía solo.": "Escreve uma mensagem cujo gancho é este sinal, com o estilo, as regras e o conhecimento da sua empresa com que você treinou a IA. Ela vai para a caixa de resposta para você editar; nunca é enviada sozinha.",
  "Conecta y configura los canales por los que salen tus campañas y llegan las respuestas a la Bandeja. Email, WhatsApp y LinkedIn son los pasos de tus cadencias; Llamadas define con qué llamas desde Listas, la Bandeja y la cola «Por llamar».": "Conecte e configure os canais pelos quais saem suas campanhas e chegam as respostas na Caixa de entrada. Email, WhatsApp e LinkedIn são as etapas das suas cadências; Ligações define como você liga a partir de Listas, da Caixa de entrada e da fila «Para ligar».",
  "Conecta un canal para ver aquí su configuración.": "Conecte um canal para ver aqui a configuração dele.",
  "Ver la cola de llamadas": "Ver a fila de ligações",
  "Ver la cola": "Ver a fila",
  "Sin conectar. El asistente te guía paso a paso, también si todavía no tienes cuenta.": "Não conectado. O assistente guia você passo a passo, mesmo se você ainda não tiver conta.",
  "Revisar en Canales": "Revisar em Canais",
  "Falta el webhook de respuestas": "Falta o webhook de respostas",
  "Una campaña combina Email, WhatsApp, LinkedIn y llamadas en una sola cadencia y se detiene sola cuando el lead responde por cualquier canal. Conecta al menos un canal en «Canales» para empezar.": "Uma campanha combina Email, WhatsApp, LinkedIn e ligações em uma única cadência e para sozinha quando o lead responde por qualquer canal. Conecte pelo menos um canal em «Canais» para começar.",
  "Conectar canales": "Conectar canais",
  "Conecta al menos un canal en «Canales»": "Conecte pelo menos um canal em «Canais»",
  "Llama con un clic desde Listas, la Bandeja y la cola «Por llamar» de tus campañas: con el dialer de Predictable (grabación, transcripción y Meeting Coach en vivo) o con tu proveedor (CloudTalk, Aircall o Ringover).": "Ligue com um clique a partir de Listas, da Caixa de entrada e da fila «Para ligar» das suas campanhas: com o discador do Predictable (gravação, transcrição e Meeting Coach ao vivo) ou com o seu provedor (CloudTalk, Aircall ou Ringover).",
