  "Una plataforma en vez de cinco, y los datos fluyen de un paso al siguiente.": "Uma plataforma no lugar de cinco, e os dados fluem de uma etapa para a próxima.",
  "Precios de lista mensuales publicados por cada proveedor o reportados por terceros en octubre de 2026, plan de entrada, sin impuestos. Gong no publica precios: usamos una estimación de terceros. Las funciones y precios de cada proveedor pueden cambiar. Los canales (tu Apollo, tu WhatsApp Business y tu LinkedIn) se conectan con tus propias cuentas.": "Preços de tabela mensais publicados por cada fornecedor ou informados por terceiros em outubro de 2026, plano de entrada, sem impostos. A Gong não publica preços: usamos uma estimativa de terceiros. As funções e preços de cada fornecedor podem mudar. Os canais (sua Apollo, seu WhatsApp Business e seu LinkedIn) se conectam com as suas próprias contas.",
