  "Sin permanencia.": "Sem fidelidade.",
  "Starter se paga con tarjeta (Stripe, en USD) y se cancela cuando quieras. Los créditos del plan se renuevan cada mes; las recargas no vencen.": "O Starter é pago com cartão (Stripe, em USD) e pode ser cancelado quando quiser. Os créditos do plano renovam todo mês; as recargas não vencem.",
  "Tus propias cuentas.": "Suas próprias contas.",
  "Conectas tu Apollo, tu WhatsApp Business y tu LinkedIn. Si no las tienes, te guiamos para crearlas en minutos.": "Você conecta sua Apollo, seu WhatsApp Business e seu LinkedIn. Se não tiver, guiamos você para criá-las em minutos.",
  "Preguntas frecuentes": "Perguntas frequentes",
  "Lo que nos preguntan antes de empezar.": "O que nos perguntam antes de começar.",
  "¿Qué incluye la prueba gratis?": "O que inclui o teste grátis?",
  "300 créditos por 30 días si te registras con el email de tu empresa, o 100 sin vencimiento con un email personal. No pedimos tarjeta. Con eso configuras tu contexto, recibes tu análisis de mercado, activas tu primer detector del Radar y lanzas tu primera campaña.": "300 créditos por 30 dias se você se cadastrar com o e-mail da sua empresa, ou 100 sem vencimento com um e-mail pessoal. Não pedimos cartão. Com isso você configura seu contexto, recebe sua análise de mercado, ativa seu primeiro detector do Radar e lança sua primeira campanha.",
  "¿Necesito una cuenta de Apollo?": "Preciso de uma conta da Apollo?",
  "Sí. Para buscar contactos conectas tu propia cuenta de Apollo (tiene un plan gratuito). Así los datos que revelas son tuyos y no gastan créditos de Predictable.": "Sim. Para buscar contatos você conecta sua própria conta da Apollo (tem um plano gratuito). Assim os dados que você revela são seus e não gastam créditos da Predictable.",
  "¿Reemplaza a mi CRM?": "Substitui o meu CRM?",
  "Puede hacerlo: incluye oportunidades, cuentas y tareas. Si ya usas HubSpot, Pipedrive, Salesforce, Zoho, Kommo, Bitrix24 o RD Station, Predictable AI se conecta y sincroniza en lugar de duplicar.": "Pode substituir: inclui oportunidades, contas e tarefas. Se você já usa HubSpot, Pipedrive, Salesforce, Zoho, Kommo, Bitrix24 ou RD Station, a Predictable AI se conecta e sincroniza em vez de duplicar.",
  "¿Es seguro enviar por WhatsApp y LinkedIn?": "É seguro enviar pelo WhatsApp e pelo LinkedIn?",
  "WhatsApp sale por tu número oficial con plantillas aprobadas por Meta, y vigilamos la calidad del número para frenar antes de un bloqueo. En LinkedIn respetamos topes diarios y semanales por cuenta. Toda baja se respeta en todos los canales.": "O WhatsApp sai pelo seu número oficial com templates aprovados pela Meta, e monitoramos a qualidade do número para frear antes de um bloqueio. No LinkedIn respeitamos limites diários e semanais por conta. Todo descadastro é respeitado em todos os canais.",
  "¿La IA inventa datos o casos de éxito?": "A IA inventa dados ou casos de sucesso?",
  "No. Los mensajes solo citan los clientes y resultados que tú cargas. Si una respuesta no tiene evidencia, la marcamos como «No encontrado» en vez de adivinar.": "Não. As mensagens só citam os clientes e resultados que você carrega. Se uma resposta não tem evidência, marcamos como «Não encontrado» em vez de adivinhar.",
  "¿Cuál es la diferencia entre Starter y Growth?": "Qual é a diferença entre Starter e Growth?",
  "Con Starter tu equipo usa la plataforma. Con Growth nuestro equipo la opera contigo: estrategia, listas, cadencias y mensajes, con revisiones de resultados.": "Com o Starter, sua equipe usa a plataforma. Com o Growth, nossa equipe a opera com você: estratégia, listas, cadências e mensagens, com revisões de resultados.",
  "¿En qué países funciona?": "Em quais países funciona?",
  "En toda Latam y también fuera de ella. Los registros públicos cubren Brasil, México y Colombia, y la plataforma está en español, inglés y portugués.": "Em toda a América Latina e também fora dela. Os registros públicos cobrem Brasil, México e Colômbia, e a plataforma está em espanhol, inglês e português.",
