  "Una biblioteca de más de 100 detectores vigila contrataciones, rondas de inversión, cambios de liderazgo, licitaciones, noticias y la huella digital de cada empresa, y te dice quién es el decisor. Cada día recibes las 25 señales con más puntaje.": "Uma biblioteca com mais de 100 detectores monitora contratações, rodadas de investimento, mudanças de liderança, licitações, notícias e a pegada digital de cada empresa, e diz quem é o decisor. Todo dia você recebe os 25 sinais com maior pontuação.",
  "Datos de contacto de varias fuentes": "Dados de contato de várias fontes",
  "Buscas personas y empresas por industria, tamaño, país y cargo, y para cada decisor consultamos varias bases de datos en cascada hasta encontrar su email y su móvil. Adaptadas a Latam: teléfonos en el formato de cada país, móvil o fijo, y si tiene WhatsApp. Verificamos cada email y solo pagas por dato encontrado.": "Você busca pessoas e empresas por setor, porte, país e cargo, e para cada decisor consultamos várias bases de dados em cascata até encontrar o e-mail e o celular. Adaptadas à América Latina: telefones no formato de cada país, celular ou fixo, e se tem WhatsApp. Verificamos cada e-mail e você só paga pelo dado encontrado.",
