  "Sofía, vi que FinPago cerró su Serie B y está contratando vendedores en Colombia. Cuando un equipo crece así de rápido, lo primero que se rompe es el seguimiento de los leads. ¿Te muestro cómo lo resolvió otra fintech en 15 minutos?": "Sofía, vi que a FinPago fechou a Série B e está contratando vendedores na Colômbia. Quando um time cresce rápido assim, a primeira coisa que quebra é o follow-up dos leads. Posso te mostrar em 15 minutos como outra fintech resolveu isso?",
