  "Una plataforma en vez de cuatro, y los datos fluyen de un paso al siguiente.": "Uma plataforma em vez de quatro, e os dados fluem de uma etapa para a seguinte.",
  "Una herramienta por categoría: Apollo ya trae secuencias de email, así que no sumamos Instantly ni Lemlist aparte. Precios de lista mensuales publicados por cada proveedor o reportados por terceros en octubre de 2026, plan de entrada, sin impuestos. Gong no publica precios: usamos una estimación de terceros. Las funciones y precios de cada proveedor pueden cambiar. Los canales (tu Apollo, tu WhatsApp Business y tu LinkedIn) se conectan con tus propias cuentas.": "Uma ferramenta por categoria: o Apollo já traz sequências de e-mail, então não somamos Instantly nem Lemlist à parte. Preços de tabela mensais publicados por cada fornecedor ou informados por terceiros em outubro de 2026, plano de entrada, sem impostos. O Gong não publica preços: usamos uma estimativa de terceiros. As funções e os preços de cada fornecedor podem mudar. Os canais (seu Apollo, seu WhatsApp Business e seu LinkedIn) se conectam com suas próprias contas.",
  "Nace Eleva": "Nasce a Eleva",
