  "Con Starter tu equipo usa la plataforma. Con Growth nos comprometemos por contrato a un número de reuniones calificadas al mes y nuestro equipo hace todo el trabajo: estrategia, listas, mensajes, cadencias y seguimiento. Tu equipo solo llega a la reunión.": "Com o Starter, o seu time usa a plataforma. Com o Growth, nos comprometemos por contrato com um número de reuniões qualificadas por mês e o nosso time faz todo o trabalho: estratégia, listas, mensagens, cadências e follow-up. O seu time só aparece na reunião.",
